local({
  slot_ids <- sub("^jikan13_Q7_", "", grep("^jikan13_Q7_[0-9]{3}$", names(tbl), value = TRUE))
  by_medium <- sapply(list(c(20, 3), 19), function(codes) {
    tallies <- Map(
      function(day, off_days) {
        counted <- with_parent <- has_coded <- numeric(nrow(tbl))
        episode_parent <- rep(NA, nrow(tbl))
        previous <- rep(NA_real_, nrow(tbl))
        for (id in slot_ids) {
          code <- as.numeric(tbl[[paste0(day, "_Q7_", id)]])
          companions <- sapply(tbl[paste0(day, "_Q7_", id, "_", 1:4)], as.numeric)
          named <- rowSums(companions >= 1 & companions <= 6, na.rm = TRUE) > 0
          parent <- rowSums(companions == 2 | companions == 3, na.rm = TRUE) > 0
          episode_parent <- ifelse(named, parent, ifelse(code == previous, episode_parent, NA))
          active <- code %in% codes
          counted <- counted + (active & !is.na(episode_parent))
          with_parent <- with_parent + (active & episode_parent %in% TRUE)
          has_coded <- has_coded + (code != 99)
          previous <- code
        }
        kept <- has_coded > 0 & !as.numeric(tbl[[paste0(day, "_Q1")]]) %in% off_days
        cbind(counted = ifelse(kept, counted, NA), with_parent = ifelse(kept, with_parent, NA))
      },
      c("jikan13", "jikan9", "jikan10"),
      list(numeric(), 26, c(11, 12, 27))
    )
    weighted <- sapply(c("counted", "with_parent"), function(part) {
      we <- rowMeans(cbind(tallies$jikan9[, part], tallies$jikan10[, part]), na.rm = TRUE)
      5 * tallies$jikan13[, part] + 2 * replace(we, is.nan(we), NA)
    })
    share <- ifelse(weighted[, "counted"] > 0, weighted[, "with_parent"] / weighted[, "counted"], NA)
    as.integer(cut(share, c(-Inf, 0, 0.1, 0.35, 0.7, 1)))
  })
  c("Never", "Rarely", "Sometimes", "Often", "Always")[pmax(by_medium[, 1], by_medium[, 2], na.rm = TRUE)]
})

local({
  slots <- sapply(tbl[grep("^jikan13_Q7_[0-9]{3}$", names(tbl))], as.numeric)
  hours <- rowSums(matrix(slots %in% c(20, 3), nrow = nrow(slots))) * 15 / 60
  if_else(rowSums(slots != 99) > 0, hours, NA_real_)
})

local({
  days <- mapply(
    function(day, off_days) {
      slots <- sapply(tbl[grep(paste0("^", day, "_Q7_[0-9]{3}$"), names(tbl))], as.numeric)
      hours <- rowSums(matrix(slots %in% c(20, 3), nrow = nrow(slots))) * 15 / 60
      kept <- rowSums(slots != 99) > 0 & !as.numeric(tbl[[paste0(day, "_Q1")]]) %in% off_days
      if_else(kept, hours, NA_real_)
    },
    c("jikan9", "jikan10"),
    list(26, c(11, 12, 27))
  )
  we <- rowMeans(days[, c("jikan9", "jikan10")], na.rm = TRUE)
  we <- replace(we, is.nan(we), NA)
  we
})

local({
  days <- mapply(
    function(day, off_days) {
      slots <- sapply(tbl[grep(paste0("^", day, "_Q7_[0-9]{3}$"), names(tbl))], as.numeric)
      hours <- rowSums(matrix(slots %in% c(20, 3), nrow = nrow(slots))) * 15 / 60
      kept <- rowSums(slots != 99) > 0 & !as.numeric(tbl[[paste0(day, "_Q1")]]) %in% off_days
      if_else(kept, hours, NA_real_)
    },
    c("jikan13", "jikan9", "jikan10"),
    list(numeric(), 26, c(11, 12, 27))
  )
  we <- rowMeans(days[, c("jikan9", "jikan10")], na.rm = TRUE)
  we <- replace(we, is.nan(we), NA)
  (5 * days[, "jikan13"] + 2 * we) / 7
})

